[
  {
    "statement": "No studies were found that evaluated the effects of breeding bats in captivity to supplement wild populations affected by white-nose syndrome.",
    "citations": [
      "2009"
    ]
  },
  {
    "statement": "Eight studies on breeding bats in captivity found that the reproductive success of captive-born pups varied.",
    "citations": []
  },
  {
    "statement": "Eight studies on breeding bats in captivity found that the survival of captive-born pups varied.",
    "citations": []
  },
  {
    "statement": "In six studies, 6% to 100% of wild-caught female bats successfully reared young in captivity.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "In two other studies, some bats born in captivity also reproduced.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "Survival rates for captive-born pups ranged from 20% to 100% from 10 days to adulthood, as observed in seven studies.",
    "citations": []
  },
  {
    "statement": "In another study, two of five captive-born pups survived and were hand-reared.",
    "citations": [
      "2053"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects on bat populations of training arborists and forestry operatives to identify potential bat roosts.",
    "citations": [
      "1981"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on bat populations of protecting roost trees during forest operations.",
    "citations": [
      "1982"
    ]
  }
]
